SELECT CASE WHEN pressure >= 1023 THEN 'PREMIUM' ELSE 'STANDARD' END AS pressure_tier, DATE_TRUNC('HOUR', reading_ts) AS hour_window, STDDEV_SAMP(status_bits) AS status_bits_stddev, COUNT(DISTINCT device_code) AS distinct_device_codes, GROUPING(CASE WHEN pressure >= 1023 THEN 'PREMIUM' ELSE 'STANDARD' END) AS gid FROM device_readings GROUP BY CUBE (CASE WHEN pressure >= 1023 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('HOUR', reading_ts))
